--- 消耗预览：展示选中狗粮/碎片的总消耗，以及矿石兑换碎片的明细
--- 数据仅供 UiRoleCostPreviewPopup 一次性展示，直接在 View 组装弹窗数据结构
function XUiEquipPartnerOneKeyCultureSelectClipPopup:OnBtnPreviewClick(eventData)
    local mainControl = self._Control:GetOneKeyCultureMainControl()
    local partner = mainControl:GetCurPartnerEntity()
    if not partner then
        return
    end
    local foodSelectControl = mainControl:GetFoodSelectControl()

    local chipItemId = partner:GetChipItemId()
    local chipNeedCount = partner:GetChipNeedCount() or 0

    -- 总碎片 = 狗粮 + 散碎片 + 矿石兑换格；拆出兑换部分
    local totalChips = foodSelectControl:GetFoodSelectExpCount()
    local exchangeChips = foodSelectControl:GetSelectOreExchangeChipCount()
    local ownChips = totalChips - exchangeChips

    local costList = {}
    if ownChips > 0 then
        table.insert(costList, { Id = chipItemId, Count = ownChips, IsExchange = false })
    end
    if exchangeChips > 0 then
        table.insert(costList, { Id = chipItemId, Count = exchangeChips, IsExchange = true })
    end
    for _, cost in ipairs(foodSelectControl:GetFoodSelectMoneyCostList()) do
        table.insert(costList, { Id = cost.Id, Count = cost.Count, IsExchange = false })
    end

    local sections = {}
    if not XTool.IsTableEmpty(costList) then
        table.insert(sections, { Title = XUiHelper.GetText("PartnerOneKeyStarUpTitle"), CostList = costList })
    end

    -- 矿石兑换明细
    local exchangeList = {}
    if exchangeChips > 0 then
        local _, exchangeChipCount, consumeId, consumeCount =
            XMVCA.XPartner.Util.GetOreExchangeChipCostByCount(chipItemId, exchangeChips)
        if exchangeChipCount >= exchangeChips then
            table.insert(exchangeList, {
                ItemId = chipItemId,
                RewardCount = exchangeChipCount,
                ConsumeList = { { Id = consumeId, Count = consumeCount } },
            })
        end
    end

    XLuaUiManager.Open("UiRoleCostPreviewPopup", { Sections = sections, ExchangeList = exchangeList })
end

