function XUiEquipPartnerOneKeyCultureSelectClipPopup:_RefreshQuality()
    local mainControl = self._Control:GetOneKeyCultureMainControl()
    local partner = mainControl:GetCurPartnerEntity()
    if not partner then
        return
    end

    local foodSelectControl = mainControl:GetFoodSelectControl()
    local curQuality = partner:GetQuality()
    local afterQuality = curQuality

    local selectCount = foodSelectControl:GetFoodSelectCount()
    if selectCount > 0 then
        local canUpCount = foodSelectControl:GetFoodSelectCanUpCount()
        afterQuality = math.min(curQuality + canUpCount, partner:GetQualityLimit())
    end

    local isQualityUp = afterQuality > curQuality
    self.RImgNowQuality:SetRawImage(XMVCA.XCharacter:GetCharacterQualityIcon(curQuality))
    self.GoImgArrow.gameObject:SetActiveEx(isQualityUp)
    self.RImgAfterQuality.gameObject:SetActiveEx(isQualityUp)
    if isQualityUp then
        self.RImgAfterQuality:SetRawImage(XMVCA.XCharacter:GetCharacterQualityIcon(afterQuality))
    end
end

function XUiEquipPartnerOneKeyCultureSelectClipPopup:_RefreshPartnerList()
    local mainControl = self._Control:GetOneKeyCultureMainControl()
    local partnerList = mainControl:GetQualityUpPartnerListAndClipCount()
    local partnerListCount = #partnerList

    local partner = mainControl:GetCurPartnerEntity()
    local chipItemId = partner:GetChipItemId()
    local foodSelectControl = mainControl:GetFoodSelectControl()
    local totalChips = foodSelectControl:GetLooseChipCount()
    local chipNeedCount = partner:GetChipNeedCount()
    local fullClipFoodCount = math.floor(totalChips / chipNeedCount)
    foodSelectControl:InitOreExchangeRemainChipCount(totalChips % chipNeedCount)
    local remainChipCount = foodSelectControl:GetOreExchangeRemainChipCount() or 0
    local oreExchangeFoodCount = foodSelectControl:GetOreExchangePartnerCount()
    self._OreExchangeFoodCount = oreExchangeFoodCount
    local hasLooseChipGrid = remainChipCount > 0 and oreExchangeFoodCount <= 0
    local clipFoodCount = fullClipFoodCount + (hasLooseChipGrid and 1 or 0)
    local totalCount = partnerListCount + clipFoodCount + oreExchangeFoodCount

    self:_EnsureGridCount(totalCount)

    for index = 1, totalCount do
        local grid = self._GridPartnerFragmentList[index]
        if index <= partnerListCount then
            grid:RefreshByPartner(partnerList[index])
        elseif index <= partnerListCount + clipFoodCount then
            local clipIndex = index - partnerListCount
            local curCount = chipNeedCount
            if hasLooseChipGrid and clipIndex == clipFoodCount then
                curCount = remainChipCount
            end
            grid:RefreshByPartnerClip(chipItemId, clipIndex, curCount)
        else
            local oreExchangeClipIndex = index - partnerListCount - clipFoodCount
            local exchangeChipCount = foodSelectControl:GetOreExchangeClipNeedChipCount(oreExchangeClipIndex)
            local ownChipCount = oreExchangeClipIndex == 1 and remainChipCount or 0
            local isMixed = ownChipCount > 0 and exchangeChipCount < chipNeedCount
            local curCount = isMixed and ownChipCount or chipNeedCount
            grid:RefreshByOreExchangeClip(chipItemId, oreExchangeClipIndex, curCount, isMixed,
                ownChipCount, exchangeChipCount)
        end
        grid:Open()
    end

    for index = totalCount + 1, #self._GridPartnerFragmentList do
        self._GridPartnerFragmentList[index]:Close()
    end
end

function XUiEquipPartnerOneKeyCultureSelectClipPopup:_RefreshCost()
    local mainControl = self._Control:GetOneKeyCultureMainControl()
    local foodSelectControl = mainControl:GetFoodSelectControl()
    local selectCount = foodSelectControl:GetFoodSelectCount()
    if selectCount == 0 then
        self.TxtCost.text = XUiHelper.GetText("PartnerOneKeySelectPartnerTip")
        self.TxtCost.color = self._CostNormalColor
    else
        local costMoney = foodSelectControl:GetFoodSelectCostMoney()
        local coinItemId = XDataCenter.ItemManager.ItemId.Coin
        local haveMoney = mainControl:GetBaseCostControl():GetItemHaveCount(coinItemId)
        self.TxtCost.text = costMoney
        self.TxtCost.color = haveMoney < costMoney and self._CostLackColor or self._CostNormalColor
    end
end

function XUiEquipPartnerOneKeyCultureSelectClipPopup:_EnsureGridCount(count)
    local XUiEquipPartnerOneKeyCultureSelectCell = require("XUi/XUiPartnerOneKeyCulture/XUiEquipPartnerOneKeyCultureSelectClipPopup/XUiEquipPartnerOneKeyCultureSelectCell")
    while #self._GridPartnerFragmentList < count do
        local ui = CS.UnityEngine.Object.Instantiate(self.UiEquipGridPartnerFragment, self.UiEquipGridPartnerFragment.transform.parent)
        ui.gameObject:SetActiveEx(true)
        local grid = XUiEquipPartnerOneKeyCultureSelectCell.New(ui, self)
        table.insert(self._GridPartnerFragmentList, grid)
    end
end

return XUiEquipPartnerOneKeyCultureSelectClipPopup
